export const DECISION_CATEGORIES=[{id:'foundational',name:'Foundational choice',plural:'Foundational choices'},{id:'structural',name:'Structural decision',plural:'Structural decisions'},{id:'cross-cutting',name:'Cross-cutting concern',plural:'Cross-cutting concerns'},{id:'trade-off',name:'Trade-off',plural:'Trade-offs and alternatives'},{id:'additional',name:'Additional decision',plural:'Additional decisions'}];
