export const decisionCategory=d=>DECISION_CATEGORIES.find(c=>c.id===d?.category)?.id||'';
export const chosen=d=>d?.alternatives.find(a=>a.id===d.selectedAlternativeId);
// Round 12 (E2, GR-DRF-22): the alternative Sol prefers on a decision it drafted, recorded as a recommendation
// {alternativeId, rationale, driverIds, by: 'sol'} and never as the choice. selectedAlternativeId is the person's working
// choice (decision.choose), and every reader takes it as deciding: the SDD's open items and executive edition, this
// chapter's checks once the decision is kept, the decisions a responsibility reads and the utility tree. A
// recommendation is read by none of them: a person accepts it by choosing that alternative, or rejects it by choosing
// another or saving the decision with recommendation null. Only Sol's draft records one, while the decision is still
// its proposal. Sol's assessment of an alternative against a driver is marked by: 'sol' the same way, kept while the
// assessment is not sent again, and the person's once they send it. Round 25 (D-25-09): one AIW's rules drafted from the
// SA Playbook's marks is marked by: 'rules', kept and dropped the same way.
