  if(d.requirementIds.some(id=>!requirementIds.has(id))||d.driverIds.some(id=>!driverIds.has(id))||d.requirementGroupIds?.some(id=>!groupIds.has(id))||d.stakeholderIds?.some(id=>!people.has(id))||d.dependsOn?.some(id=>!decisionIds.has(id)))add('broken-links',d.id,'Repair missing source references','A linked requirement, group, driver, stakeholder or decision no longer exists.');
