export const decisionReviewCurrent=p=>p.decisions.review?.version===p.decisions.version&&p.decisions.review?.sourceVersion===p.contentVersion&&p.decisions.review?.qualityVersion===p.quality.version;
export const decisionHandoffCurrent=p=>p.decisions.handoff?.version===p.decisions.version&&p.decisions.handoff?.sourceVersion===p.contentVersion&&p.decisions.handoff?.qualityVersion===p.quality.version;
