const FIELD_LABELS={impact:'Impact (gains and costs)',stakeholderNote:'Stakeholders',dependencies:'Dependencies',licensing:'Licensing',skills:'Skills',documentation:'Documentation'};
function exportDecisionsMarkdownOf(p){const codes=new Map(p.quality.drivers.map(q=>[q.id,driverCode(p,q)])),refs=new Map([...(p.logical?.responsibilities||[]),...(p.realisation?.components||[])].map(r=>[r.id,r.ref||r.id])),ref=id=>refs.get(id)||id;return '# AIW V5 · '+p.name+'\n\n## Chapter 3 — Decisions\n\nDecision revision '+p.decisions.version+' · Requirements '+p.contentVersion+' · Quality '+p.quality.version+'.\n\nComparisons show effects, reasons, and evidence. The weighing of the alternatives is shown as arithmetic on the recorded effects (High 3, Medium 2, Low 1); it does not choose. Architect acceptance and governance approval are separate.\n\n'+p.decisions.records.map(d=>`### ${d.id} · ${d.question}\n\nRevision ${d.revision} · ${statusLabel(d)} · ${governanceLabel(d,p)}\n\n${decisionCategory(d)?'Category: '+DECISION_CATEGORIES.find(c=>c.id===d.category).name+'\n\n':''}Owner: ${d.owner}\n\nSource: ${d.source} (${d.origin})\n\nContext: ${d.context}\n\nSelected: ${chosen(d)?.id||'None'} · ${chosen(d)?.title||'No working choice'}\n\n${recommendation(d)?'Preferred by Sol (a proposal, not accepted): '+recommendation(d).alternativeId+' · '+(d.alternatives.find(a=>a.id===recommendation(d).alternativeId)?.title||'')+'. '+recommendation(d).rationale+'\n\n':''}Rationale: ${d.rationale||'Missing'}\n\nAssumptions: ${d.assumptions||'None recorded'} — ${d.assumptionsResolved?'confirmed':'open'}\n\nAssumption evidence: ${d.assumptionEvidence}\n\n${d.assumptionIds?.length?'Assumption records: '+d.assumptionIds.map(id=>{const a=p.artefacts.find(x=>x.id===id);return id+' · '+(a?.title||'missing')+' ('+(a?.confirmed?'confirmed':'not confirmed')+')';}).join('; ')+'\n\n':''}Risks: ${d.risks}\n\nTreatment: ${d.mitigation}\n\n${d.stakeholderIds?.length?'Stakeholder records: '+d.stakeholderIds.map(id=>id+' · '+(p.artefacts.find(a=>a.id===id)?.title||'missing')).join('; ')+'\n\n':''}${DECISION_FIELDS.filter(k=>d[k]).map(k=>FIELD_LABELS[k]+': '+d[k]+'\n\n').join('')}${d.dependsOn?.length?'Depends on: '+d.dependsOn.join(', ')+'\n\n':''}Requirements: ${d.requirementIds.join(', ')}\n\n${d.requirementGroupIds?.length?'Requirement groups: '+d.requirementGroupIds.join(', ')+'\n\n':''}Drivers: ${d.driverIds.map(id=>id+(codes.get(id)?' ('+codes.get(id)+')':'')).join(', ')}\n\nModel impact: ${impactCurrent(p,d)?'Applied for the current decision':'Unapplied or requires review'}\n\nGovernance evidence: ${d.governance?.evidence||'Not recorded'}\n\n`+d.alternatives.map(a=>`#### ${a.id} · ${a.title}\n\n${a.summary}\n\nBenefits: ${a.benefits}\n\nCosts: ${a.costs}\n\nConsequences: ${a.consequences}\n\nPattern: ${a.pattern}\n\nAnti-pattern to avoid: ${a.antiPattern}\n\n${a.rejectionReason?'Why not chosen: '+a.rejectionReason+'\n\n':''}${a.componentIds?.length?'Components: '+a.componentIds.map(ref).join(', ')+'\n\n':''}Responsibilities: ${a.responsibilityIds.map(ref).join(', ')}\n\nRelationships:\n${a.relationships.map(e=>'- '+ref(e.from)+' → '+ref(e.to)+': '+e.label).join('\n')}\n\nComparison:\n${d.driverIds.map(id=>{const v=a.assessments[id];return '- '+id+': '+(v?.effect||'unknown')+'. '+(v?.reason||'Reason missing')+' Evidence: '+(v?.evidence||'Not recorded')+(solAssessed(v)?' (assessed by Sol, not reviewed by a person)':rulesAssessed(v)?' (drafted by AIW’s rules from the SA Playbook, not reviewed by a person)':'')}).join('\n')}\n\n`).join('')+`History:\n${d.history.map(h=>'- r'+h.revision+' · '+h.event+' · '+h.at+' · '+(h.alternative||'No choice')).join('\n')||'No recorded revisions yet.'}\n\n`).join('')+'## Conflicts\n\n'+(p.decisions.conflicts.map(c=>`- ${c.id} · ${c.decisionIds.join(' / ')} · ${c.title} — ${conflictResolved(p,c)?'resolved':'open / review required'}. ${c.resolution} Owner: ${c.owner}`).join('\n')||'None recorded.')+'\n\n## Open findings\n\n'+(decisionFindings(p).map(f=>'- '+f.decisionId+': '+f.title+'. '+f.detail).join('\n')||'No findings under the current rules.')+'\n\nGuidance is rule-based. Reference examples require project-specific evidence.\n';}
